import re

def calc(expr):
    tokens = re.findall(r'\d+|[+\-*/()]', expr)
    pos = 0

    def peek():
        nonlocal pos
        if pos < len(tokens):
            return tokens[pos]
        return None

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def trunc_div(a, b):
        q = abs(a) // abs(b)
        if (a < 0) == (b < 0):
            return q
        else:
            return -q

    def parse_expr():
        val = parse_term()
        while peek() in ('+', '-'):
            op = advance()
            rhs = parse_term()
            if op == '+':
                val += rhs
            else:
                val -= rhs
        return val

    def parse_term():
        val = parse_factor()
        while peek() in ('*', '/'):
            op = advance()
            rhs = parse_factor()
            if op == '*':
                val *= rhs
            else:
                val = trunc_div(val, rhs)
        return val

    def parse_factor():
        neg = False
        while peek() == '-':
            advance()
            neg = not neg
        val = parse_primary()
        return -val if neg else val

    def parse_primary():
        tok = peek()
        if tok == '(':
            advance()
            val = parse_expr()
            # expect ')'
            if peek() == ')':
                advance()
            return val
        else:
            advance()
            return int(tok)

    result = parse_expr()
    return result

